// decode reads the rows of records, each kept to the members fields
// selects when selected, whose relations it then hydrates as the Postgres
// repository does.
func (r *AgentSQLiteRepository) decode(ctx context.Context, records []sqliteRecord, fields AgentFields, selected bool) ([]*types.Agent, error) {
	var keep map[string]bool
	if selected {
		keep = agentSQLiteMembers(fields)
	}
	rows, err := sqliteDecodeAll[types.Agent](records, keep)
	if err != nil {
		return nil, fmt.Errorf("read Agent: %w", err)
	}
	return rows, nil
}

// GetOne retrieves a single Agent by ID
func (r *AgentSQLiteRepository) GetOne(ctx context.Context, id types.IdentityUUID, opts *AgentGetOptions) (*types.Agent, error) {
	key, err := agentSQLite.keyArg(id)
	if err != nil {
		return nil, err
	}
	if err := r.requireReach(ctx, key, false); err != nil {
		return nil, err
	}
	record, err := agentSQLite.one(ctx, r.q(), agentSQLite.st.getOne+agentSQLite.st.live, key)
	if err != nil {
		return nil, err
	}
	var fields AgentFields
	if opts != nil {
		fields = opts.Fields
	}
	rows, err := r.decode(ctx, []sqliteRecord{record}, fields, !fields.IsZero())
	if err != nil {
		return nil, err
	}
	return rows[0], nil
}

// GetManyByIDs retrieves the live Agent rows of ids, by ID: a query of
// at most as many keys as SQLite binds the parameters of, as many times
// as the keys take.
func (r *AgentSQLiteRepository) GetManyByIDs(ctx context.Context, ids []types.IdentityUUID) (map[types.IdentityUUID]*types.Agent, error) {
	out := make(map[types.IdentityUUID]*types.Agent, len(ids))
	if len(ids) == 0 {
		return out, nil
	}
	seen := make(map[types.IdentityUUID]bool, len(ids))
	var keys []any
	for _, id := range ids {
		if seen[id] {
			continue
		}
		seen[id] = true
		key, err := agentSQLite.keyArg(id)
		if err != nil {
			return nil, err
		}
		keys = append(keys, key)
	}
	var records []sqliteRecord
	// The access conditions bind their own parameters after the keys
	// (D156): as many as the caller's audience and grants take.
	var held []any
	sqliteAccessConditions(ctx, "Agent", &held, false)
	most := max(1, 32766-len(held))
	for start := 0; start < len(keys); start += most {
		// A copy of the batch's keys, which the conditions' values follow.
		args := append([]any(nil), keys[start:min(start+most, len(keys))]...)
		placeholders := make([]string, len(args))
		for i := range args {
			placeholders[i] = fmt.Sprintf("?%d", i+1)
		}
		query := fmt.Sprintf(agentSQLite.st.getMany, strings.Join(placeholders, ", ")) + agentSQLite.st.live
		// The rows the caller sees alone, in the same statement: a row the
		// caller does not see is one that is not there (D156).
		if conditions := sqliteAccessConditions(ctx, "Agent", &args, false); len(conditions) > 0 {
			query += " AND " + strings.Join(conditions, " AND ")
		}
		read, err := agentSQLite.query(ctx, r.q(), query, args...)
		if err != nil {
			return nil, err
		}
		records = append(records, read...)
	}
	rows, err := r.decode(ctx, records, AgentFields{}, false)
	if err != nil {
		return nil, err
	}
	for _, row := range rows {
		if id, ok := sqliteUUIDOf(row.Id); ok {
			out[id] = row
		}
	}
	return out, nil
}

// where is the WHERE of filter, and the live rows alone unless
// includeDeleted.
func (r *AgentSQLiteRepository) where(filter *AgentFilter, args *[]any, includeDeleted bool) string {
	return agentSQLite.where(filter.sqliteConditions(args), includeDeleted)
}

// accessConditions are the filter's conditions, each value appended to
// args, then those that keep the rows to what the operation's caller sees,
// or with write may write (D156, D182): a condition through a relation
// holds the rows it reads to the caller too.
func (r *AgentSQLiteRepository) accessConditions(ctx context.Context, filter *AgentFilter, args *[]any, write bool) []string {
	var conditions []string
	if filter != nil {
		filter.scope = sqliteAccessScopeOf(ctx)
		conditions = filter.sqliteConditions(args)
	}
	return append(conditions, sqliteAccessConditions(ctx, "Agent", args, write)...)
}

// accessWhere is where, kept to what the operation's caller sees, or with
// write may write.
func (r *AgentSQLiteRepository) accessWhere(ctx context.Context, filter *AgentFilter, args *[]any, includeDeleted, write bool) string {
	return agentSQLite.where(r.accessConditions(ctx, filter, args, write), includeDeleted)
}

// requireReach returns ErrNotFound unless the row whose key binds as key
// is one the operation's caller sees, or with write may write (D156).
func (r *AgentSQLiteRepository) requireReach(ctx context.Context, key any, write bool) error {
	return sqliteRequireReach(ctx, r.q(), "Agent", agentSQLite.quoted, key, write)
}

// requireCreated returns ErrAccessRefused unless a party's or an agent
// run's grants reach every one of rows, the rows a create made (D156).
func (r *AgentSQLiteRepository) requireCreated(ctx context.Context, q sqliteQuerier, rows []*types.Agent) error {
	if !accessGranted(ctx) {
		return nil
	}
	keys := make([]any, 0, len(rows))
	for _, row := range rows {
		if row.Id == nil {
			return fmt.Errorf("Agent: %w", ErrAccessRefused)
		}
		key, err := agentSQLite.keyArg(*row.Id)
		if err != nil {
			return err
		}
		keys = append(keys, key)
	}
	return sqliteRequireCreated(ctx, q, "Agent", agentSQLite.quoted, keys)
}

// orderBy is the ORDER BY of orderBy.
func (r *AgentSQLiteRepository) orderBy(orderBy []AgentOrderBy) string {
	fields := make([]string, len(orderBy))
	desc := make([]bool, len(orderBy))
	for i, order := range orderBy {
		fields[i], desc[i] = string(order.Field), order.Desc
	}
	return agentSQLite.orderBy(fields, desc, AgentQuotedFields)
}

// FindOne retrieves the first Agent matching the filter
func (r *AgentSQLiteRepository) FindOne(ctx context.Context, filter *AgentFilter, opts *AgentFindOptions) (*types.Agent, error) {
	if opts == nil {
		opts = &AgentFindOptions{}
	}
	var args []any
	where := r.accessWhere(ctx, filter, &args, opts.IncludeDeleted, false)
	record, err := agentSQLite.findOne(ctx, r.q(), where, r.orderBy(opts.OrderBy), args)
	if err != nil {
		return nil, err
	}
	rows, err := r.decode(ctx, []sqliteRecord{record}, opts.Fields, !opts.Fields.IsZero())
	if err != nil {
		return nil, err
	}
	return rows[0], nil
}

// FindMany retrieves multiple Agent records matching the filter, and how
// many it matches in all, -1 when the options skip the count
func (r *AgentSQLiteRepository) FindMany(ctx context.Context, filter *AgentFilter, opts *AgentFindOptions) ([]*types.Agent, int, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, 0, fmt.Errorf("fields must be specified in FindOptions for performance")
	}
	var args []any
	where := r.accessWhere(ctx, filter, &args, opts.IncludeDeleted, false)
	records, total, err := agentSQLite.findMany(ctx, r.q(), where, r.orderBy(opts.OrderBy), args, opts.Limit, opts.Offset, opts.SkipCount)
	if err != nil {
		return nil, 0, err
	}
	rows, err := r.decode(ctx, records, opts.Fields, true)
	if err != nil {
		return nil, 0, err
	}
	return rows, total, nil
}

// findRelated reads the rows filter finds as FindMany reads them, with no
// count: the read that loads a relation's rows for another table's read.
func (r *AgentSQLiteRepository) findRelated(ctx context.Context, filter *AgentFilter, opts *AgentFindOptions) ([]*types.Agent, error) {
	skip := *opts
	skip.SkipCount = true
	rows, _, err := r.FindMany(ctx, filter, &skip)
	return rows, err
}

// FindPage reads a page of the Agent rows filter finds, in the
// sort's order, after the key of the page before (D60, amended).
func (r *AgentSQLiteRepository) FindPage(ctx context.Context, filter *AgentFilter, opts *AgentPageOptions) (*AgentPage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of Agent rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = AgentSortById
	}
	column, ok := agentSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: Agent sorts by id, name, purpose, instructions, task, role, model, modelSlot, sandboxSlot, image and createdAt, not %q", string(field))
	}
	var after any
	if opts.After != nil {
		if _, err := opts.After.arg(); err != nil {
			return nil, err
		}
		key, err := agentSQLite.keyArg(opts.After.Id)
		if err != nil {
			return nil, err
		}
		after = key
	}
	var args []any
	conditions := r.accessConditions(ctx, filter, &args, false)
	records, err := agentSQLite.page(ctx, r.q(), conditions, args, sqliteSort{sql: column.sql, key: column.key, nulls: column.nulls}, field == AgentSortById, opts.Sort.Desc, after, limit, opts.IncludeDeleted)
	if err != nil {
		return nil, err
	}
	// Next is the key of the page's last row, so the page reads its
	// primary key whatever Fields selects.
	fields := opts.Fields
	fields.Id = true
	rows, err := r.decode(ctx, records, fields, true)
	if err != nil {
		return nil, err
	}
	page := &AgentPage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = agentPageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

