// stampCreate sets the audit fields of who wrote input, as the Postgres
// repository's CreateOne does.
func (r *AgentSQLiteRepository) stampCreate(ctx context.Context, input *types.Agent) error {
	return nil
}

// CreateOne inserts a new Agent record
func (r *AgentSQLiteRepository) CreateOne(ctx context.Context, input *types.Agent) (*types.Agent, error) {
	if err := r.stampCreate(ctx, input); err != nil {
		return nil, err
	}
	record, err := sqliteMembersOf(input)
	if err != nil {
		return nil, fmt.Errorf("create Agent: %w", err)
	}
	written, err := agentSQLite.insert(ctx, r.q(), record)
	if err != nil {
		return nil, err
	}
	rows, err := r.decode(ctx, []sqliteRecord{written}, AgentFields{}, false)
	if err != nil {
		return nil, err
	}
	if err := r.requireCreated(ctx, r.q(), rows); err != nil {
		return nil, err
	}
	return rows[0], nil
}

// CreateMany inserts the rows in the inputs' order and returns them, in one
// transaction: a statement per run of consecutive rows that write the same
// columns, since a VALUES list on SQLite takes no DEFAULT, of at most 2184
// rows, as many as SQLite binds the parameters of (sqliteTable.insertMany).
func (r *AgentSQLiteRepository) CreateMany(ctx context.Context, inputs []*types.Agent) ([]*types.Agent, error) {
	out := make([]*types.Agent, 0, len(inputs))
	if len(inputs) == 0 {
		return out, nil
	}
	records := make([]sqliteRecord, len(inputs))
	for i, input := range inputs {
		if err := r.stampCreate(ctx, input); err != nil {
			return nil, err
		}
		record, err := sqliteMembersOf(input)
		if err != nil {
			return nil, fmt.Errorf("create Agent %d: %w", i, err)
		}
		records[i] = record
	}
	err := r.within(ctx, func(q sqliteQuerier) error {
		written, err := agentSQLite.insertMany(ctx, q, records, 2184)
		if err != nil {
			return err
		}
		rows, err := r.decode(ctx, written, AgentFields{}, false)
		if err != nil {
			return err
		}
		// A row the caller's grants do not reach rolls the whole create
		// back (D156).
		if err := r.requireCreated(ctx, q, rows); err != nil {
			return err
		}
		out = append(out, rows...)
		return nil
	})
	if err != nil {
		return nil, err
	}
	return out, nil
}

