// updatedBy is who an update says it was made by: its own UpdatedBy, the
// acting user, or nil.
func (r *AgentSQLiteRepository) updatedBy(ctx context.Context, update *AgentUpdate) (any, error) {
	return nil, nil
}

// stamped are sets with the stamps of an update after them and each
// fence they advance (D119).
func (r *AgentSQLiteRepository) stamped(ctx context.Context, update *AgentUpdate, sets []string, args []any) ([]string, []any, error) {
	by, err := r.updatedBy(ctx, update)
	if err != nil {
		return nil, nil, err
	}
	sets, args = agentSQLite.stamp(sets, args, by)
	return sets, args, nil
}

// UpdateOne sets the members update sets on the live row whose key is id.
func (r *AgentSQLiteRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *AgentUpdate) (*types.Agent, error) {
	return r.updateOne(ctx, id, update, nil)
}

// UpdateOneIfVersion updates a single Agent only if its current _version
// matches expectedVersion.
func (r *AgentSQLiteRepository) UpdateOneIfVersion(ctx context.Context, id types.IdentityUUID, expectedVersion int64, update *AgentUpdate) (*types.Agent, error) {
	return r.updateOne(ctx, id, update, &expectedVersion)
}

func (r *AgentSQLiteRepository) updateOne(ctx context.Context, id types.IdentityUUID, update *AgentUpdate, version *int64) (*types.Agent, error) {
	var args []any
	sets, _, _, err := r.sets(update, &args)
	if err != nil {
		return nil, err
	}
	if sets, args, err = r.stamped(ctx, update, sets, args); err != nil {
		return nil, err
	}
	if len(sets) == 0 {
		return nil, fmt.Errorf("no fields to update")
	}
	key, err := agentSQLite.keyArg(id)
	if err != nil {
		return nil, err
	}
	if err := r.requireReach(ctx, key, true); err != nil {
		return nil, err
	}
	record, err := agentSQLite.update(ctx, r.q(), key, sets, args, version)
	if err != nil {
		return nil, err
	}
	rows, err := r.decode(ctx, []sqliteRecord{record}, AgentFields{}, false)
	if err != nil {
		return nil, err
	}
	return rows[0], nil
}

// UpdateMany sets the members update sets on the live rows filter finds,
// and answers how many.
func (r *AgentSQLiteRepository) UpdateMany(ctx context.Context, filter *AgentFilter, update *AgentUpdate) (int, error) {
	var args []any
	sets, _, _, err := r.sets(update, &args)
	if err != nil {
		return 0, err
	}
	if sets, args, err = r.stamped(ctx, update, sets, args); err != nil {
		return 0, err
	}
	if len(sets) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}
	where := r.accessWhere(ctx, filter, &args, false, true)
	n, err := agentSQLite.exec(ctx, r.q(), fmt.Sprintf(agentSQLite.st.updateMany, strings.Join(sets, ", "), where), args...)
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}
	return n, nil
}

